"""A self-contained service folder for any bundle.

ONNX can express only some models. This path works for every one: the folder
holds the bundle, the exact environment it was built in, a server script and a
Dockerfile, so the same Python model that was validated is the one that serves.
The server refuses an unsigned bundle unless the operator vouches for it.
"""

import pathlib
from typing import Any

from scmle.contracts import errors

SERVER = '''\
"""Serves the bundled model over HTTP (generated by scmle package)."""

import logging
import os
import pathlib
import threading

from scmle.artifacts import bundle as bundle_module
from scmle.inference import serving

LOGGER = logging.getLogger("service")


def main() -> None:
    """Loads the bundle and answers requests until stopped."""
    logging.basicConfig(level=logging.INFO)
    model = bundle_module.ModelBundle.load(
        pathlib.Path(__file__).parent / "model",
        trusted=os.environ.get("SCMLE_TRUSTED") == "1",
    )
    adapter = serving.HttpServing(
        model,
        os.environ.get("HOST", "0.0.0.0"),  # nosec B104 - container service
        int(os.environ.get("PORT", "8000")),
    )
    adapter.start()
    LOGGER.info("serving %s on %s", model.info.model_name, adapter.address)
    threading.Event().wait()


if __name__ == "__main__":
    main()
'''

DOCKERFILE = """\
FROM python:{python}-slim
WORKDIR /service
COPY requirements.txt .
RUN pip install --no-cache-dir -r requirements.txt
COPY . .
ENV PORT=8000
EXPOSE 8000
HEALTHCHECK CMD python -c "import urllib.request,os; \\
urllib.request.urlopen('http://127.0.0.1:%s/health' % os.environ['PORT'])"
CMD ["python", "serve.py"]
"""

README = """\
# {name} service

Model `{name}` (version {version}), built with scmle {scmle} on
Python {python}.

## Run

    pip install -r requirements.txt
    SCMLE_TRUSTED=1 python serve.py          # unsigned bundle
    SCMLE_SIGNING_KEY=... python serve.py    # signed bundle

or build the image: `docker build -t {name} .` and
`docker run -p 8000:8000 -e SCMLE_TRUSTED=1 {name}`.

## Endpoints

* `GET /health`: status, model version and checksum.
* `GET /schema`: the columns the model needs.
* `POST /predict` with `{{"records": [{{...}}]}}`: predictions; rows that
  break the schema get a 422 with the reason.

`requirements.txt` pins the libraries the model needs; `environment.lock`
lists every package of the environment it was built in.
"""


def write_service(
    bundle: Any, destination: str | pathlib.Path, scmle_pin: str | None = None
) -> pathlib.Path:
    """Writes a deployable service folder for `bundle`.

    Args:
        bundle: A `ModelBundle`.
        destination: Folder to create (must not already hold a service).
        scmle_pin: Requirement line for the framework itself; defaults to
            the exact version that built the bundle.

    Returns:
        The folder.

    Raises:
        ArtifactError: If the destination already holds a model.
    """
    root = pathlib.Path(destination)
    if (root / "model").exists():
        raise errors.ArtifactError(f"{root} already holds a service")
    root.mkdir(parents=True, exist_ok=True)
    bundle.save(root / "model")
    info = bundle.info
    pins = [scmle_pin or f"scmle=={info.scmle_version}"]
    pins += [f"scikit-learn=={info.sklearn}", f"pandas=={info.pandas}"]
    pins += [f"{name}=={version}" for name, version in info.libraries.items()]
    (root / "requirements.txt").write_text(
        "\n".join(pins) + "\n", encoding="utf-8", newline="\n"
    )
    bundle.environment_lock(root / "environment.lock")
    (root / "serve.py").write_text(SERVER, encoding="utf-8", newline="\n")
    (root / "Dockerfile").write_text(
        DOCKERFILE.format(python=".".join(info.python.split(".")[:2])),
        encoding="utf-8",
        newline="\n",
    )
    (root / "README.md").write_text(
        README.format(
            name=info.model_name,
            version=info.model_version,
            scmle=info.scmle_version,
            python=info.python,
        ),
        encoding="utf-8",
        newline="\n",
    )
    return root
